#include <stdlib.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int *a = (int *)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    int nao_enxerga = 0;
    int max_altura = a[n - 1];

    for (int i = n - 2; i >= 0; i--) {
        if (a[i] <= max_altura) {
            nao_enxerga++;
        } else {
